import {analyticsHeaders} from './analytics.mjs';
const vi=()=>localStorage.getItem('moneyLabLanguage')!=='en',tr=(a,b)=>vi()?a:b;
export let account=null;let accountError='',working=false;
export async function accountRequest(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json',...analyticsHeaders()}:analyticsHeaders(),...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('SERVER_UNAVAILABLE');}if(!r.ok)throw Error(d.error||'SERVER_UNAVAILABLE');return d;}
export const accountReady=accountRequest('account/session').then(d=>{account=d.account;return account;}).catch(()=>{accountError='SESSION_UNAVAILABLE';return null;});
export function accountMessage(code){return ({WALLET_NOT_FOUND:tr('Mở trang trong trình duyệt DApp của OKX Wallet hoặc cài tiện ích OKX Wallet trên laptop.','Open this page in the OKX Wallet DApp browser or install its browser extension.'),4001:tr('Anh/chị đã hủy yêu cầu ví. Không có tiền được chuyển.','Wallet request cancelled. No funds were transferred.'),PROGRESS_CHANGED_REFRESH:tr('Tiến trình vừa thay đổi ở thiết bị khác. Đã tải lại; vui lòng thử lại thao tác.','Progress changed on another device. Reloaded; retry the action.'),LEAVE_ROOM_FIRST:tr('Rời phòng Duet/Group trước khi chơi Solo hoặc xóa dữ liệu.','Leave the Duet/Group room before Solo play or data deletion.'),FINISH_SOLO_FIRST:tr('Hoàn thành hoặc bỏ chặng Solo hiện tại trước.','Finish or abandon the current Solo stage first.'),PROGRESS_UNAVAILABLE:tr('Chưa lưu được quyết định. Kiểm tra kết nối rồi thử lại.','Decision not saved. Check your connection and retry.'),REACTIVATED:tr('Tài khoản đã tạo lại với 0 HUB. Chơi Dễ để tích lũy.','Account re-created with 0 HUB. Play Easy to earn HUB.'),SESSION_UNAVAILABLE:tr('Chưa kiểm tra được phiên đăng nhập. Tải lại trang để thử lại.','Could not check your session. Reload to retry.'),WALLET_CHANGED:tr('Ví đã đổi tài khoản. Vui lòng đăng xuất rồi đăng nhập ví mới.','Wallet account changed. Sign out and sign in with the new account.'),TRY_AGAIN_LATER:tr('Đã yêu cầu đăng nhập nhiều lần. Chờ 5 phút rồi thử lại.','Too many login attempts. Wait five minutes and retry.')})[code]||tr('Không thực hiện được. Mã: ','Unable to continue. Code: ')+code;}
export function mountAccount(){
 const host=document.createElement('section');host.className='account-panel';document.querySelector('main').prepend(host);
 function render(){host.innerHTML=`<div><strong>${tr('Tài khoản Money Lab','Money Lab account')}</strong><p>${account?`${account.address.slice(0,6)}…${account.address.slice(-4)} · `+tr('Lưu trên máy chủ · HUB giả lập','Server saved · Fictional HUB'):tr('Chơi thử không cần ví. Đăng nhập để lưu giữa các thiết bị và dùng chung HUB với Duet/Group.','Try without a wallet. Sign in for cross-device saves and shared Solo / Duet / Group HUB.')}</p></div><div class="account-actions">${account?`<button data-account="logout">${tr('Đăng xuất','Sign out')}</button><a href="./online.html">Duet / Group →</a><button data-account="privacy" class="secondary">${tr('Lịch sử & quyền riêng tư','History & privacy')}</button>`:`<button data-account="login" ${working?'disabled':''}>${working?tr('Đang chờ ví…','Waiting for wallet…'):tr('Đăng nhập bằng ví','Sign in with wallet')}</button>`}</div><p class="account-status" role="status">${accountError?accountMessage(accountError):tr('Đăng nhập chỉ ký thông điệp · Không phí gas · Không chuyển tiền hoặc cấp quyền token','Sign-in message only · No gas · No transfers or token approvals')}</p>`;}
 host.onclick=async e=>{const a=e.target.closest('[data-account]')?.dataset.account;if(!a||working)return;if(a==='privacy'){await privacy();return;}working=true;accountError='';render();try{
  if(a==='logout'){await accountRequest('account/logout',{});location.reload();return;}
  const provider=window.okxwallet?.ethereum||window.okxwallet||window.ethereum;if(!provider?.request)throw Error('WALLET_NOT_FOUND');
  const addresses=await provider.request({method:'eth_requestAccounts'}),address=addresses?.[0];if(!address)throw Error('WALLET_NOT_FOUND');
  const c=await accountRequest('account/challenge',{address}),hex='0x'+[...new TextEncoder().encode(c.message)].map(x=>x.toString(16).padStart(2,'0')).join('');
  const signature=await provider.request({method:'personal_sign',params:[hex,address]});const current=await provider.request({method:'eth_accounts'});if(current[0]?.toLowerCase()!==address.toLowerCase())throw Error('WALLET_CHANGED');
  const result=await accountRequest('account/verify',{nonce:c.nonce,signature});if(result.reactivated)sessionStorage.setItem('moneyLabReactivated','1');location.reload();
 }catch(e){accountError=String(e.code||e.message);}finally{working=false;render();}};
 async function privacy(){const dialog=document.createElement('dialog');dialog.className='account-dialog';dialog.innerHTML=`<h2>${tr('Lịch sử & quyền riêng tư','History & privacy')}</h2><p>${tr('Lịch sử ví lưu trên máy chủ, không ghi lên blockchain. Bản chơi thử dùng HUB giả lập, không mua bán hoặc rút tiền.','Wallet history is stored on the server, not on blockchain. HUB is fictional: no purchases, transfers or withdrawals.')}</p><p>${tr('Xóa lịch sử: xóa nhật ký và các chặng cũ; giữ số dư, cấp đã mở, thống kê tổng và bộ nhớ câu hỏi. Phải hoàn thành/bỏ chặng và rời phòng trước.','Clear history removes past journals and stages; balance, unlocks, aggregate stats and question memory remain. Finish/abandon your stage and leave the room first.')}</p><p>${tr('Xóa tài khoản: xóa hồ sơ, ván Solo và các phiên đăng nhập; ẩn tên và nhật ký cá nhân trong phòng đã kết thúc. Kết toán chung của đối thủ được giữ. Giữ mã băm địa chỉ ví để chống nhận lại thưởng khởi tạo trong thời gian bản thử nghiệm hoạt động. Thống kê sự kiện nội bộ dùng mã giả danh, chi tiết được dọn sau 90 ngày khi cập nhật thống kê; xóa tài khoản xóa chi tiết theo hồ sơ, còn tổng hợp không định danh được giữ lại. Mã băm này có thể đối chiếu nếu biết địa chỉ ví, không phải ẩn danh tuyệt đối. Đăng nhập lại cùng ví bắt đầu với 0 HUB.','Delete account removes the profile, Solo save and all sessions; anonymizes your name and personal journal in completed rooms. Shared settlement records remain. A wallet-address hash is retained for the lifetime of this prototype to prevent repeat welcome grants. First-party event details use pseudonymous identifiers and are pruned after 90 days during statistics refresh; account deletion removes account-linked details while non-identifying totals remain. It can be matched to a known address and is not fully anonymous. Signing in again starts with 0 HUB.')}</p><div id="account-history">${tr('Đang tải lịch sử…','Loading history…')}</div><div class="account-actions"><button data-privacy="clear">${tr('Xóa lịch sử','Clear history')}</button><button data-privacy="delete" class="danger-button">${tr('Xóa tài khoản','Delete account')}</button><button data-privacy="close" class="secondary">${tr('Đóng','Close')}</button></div><p role="alert" id="privacy-error"></p>`;document.body.append(dialog);dialog.showModal();let data;try{data=await accountRequest('solo/state');dialog.querySelector('#account-history').textContent=tr('Số chặng đã chơi: ','Stages played: ')+data.hub.runs+' · '+data.hub.balance+' HUB\n'+(data.hub.journey||[]).slice(0,20).map(r=>r.level+' · '+r.points+'/100 · '+(r.won?tr('Thắng','Won'):tr('Chưa đạt','Not cleared'))+' · '+(r.net>=0?'+':'')+r.net+' HUB').join('\n');}catch(e){dialog.querySelector('#privacy-error').textContent=accountMessage(e.message);}
 let deleting=false;dialog.onclick=async e=>{const a=e.target.closest('[data-privacy]')?.dataset.privacy;if(!a||deleting)return;if(a==='close'){dialog.close();dialog.remove();return;}if(!data)return;const text=a==='delete'?tr('Xóa vĩnh viễn tài khoản? HUB và tiến trình sẽ mất. Đăng nhập lại cùng ví nhận 0 HUB.','Permanently delete this account? HUB and progress will be lost. Signing in again grants 0 HUB.'):tr('Xóa lịch sử cũ? Không thể hoàn tác. Số dư và cấp độ được giữ.','Clear past history? This cannot be undone. Balance and levels remain.');if(!confirm(text))return;deleting=true;try{await accountRequest('solo/'+(a==='delete'?'delete-account':'clear-history'),{revision:data.revision,requestId:crypto.randomUUID(),confirm:a==='delete'?'DELETE':'CLEAR'});location.reload();}catch(e){dialog.querySelector('#privacy-error').textContent=accountMessage(e.message);try{data=await accountRequest('solo/state');}catch{}}finally{deleting=false;}};
 }
 render();accountReady.then(render);new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});if(sessionStorage.getItem('moneyLabReactivated')){sessionStorage.removeItem('moneyLabReactivated');accountError='REACTIVATED';render();}
}
